const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').toLowerCase().trim();
const sessionId = body.sessionId || 'default';

// Detect intent
let intent = 'general';

if (
  message.includes('cita') ||
  message.includes('agendar') ||
  message.includes('reservar') ||
  message.includes('consulta') ||
  message.includes('appointment')
) {
  intent = 'booking';
} else if (
  message.includes('horario') ||
  message.includes('hora') ||
  message.includes('disponib') ||
  message.includes('cuando') ||
  message.includes('cuándo')
) {
  intent = 'schedule';
} else if (
  message.includes('especialidad') ||
  message.includes('cirugía') ||
  message.includes('cirugia') ||
  message.includes('servicio') ||
  message.includes('qué hace') ||
  message.includes('que hace')
) {
  intent = 'specialties';
} else if (
  message.includes('precio') ||
  message.includes('costo') ||
  message.includes('cuánto') ||
  message.includes('cuanto') ||
  message.includes('tarifa')
) {
  intent = 'pricing';
} else if (
  message.includes('ubicacion') ||
  message.includes('ubicación') ||
  message.includes('dirección') ||
  message.includes('donde') ||
  message.includes('dónde')
) {
  intent = 'location';
} else if (
  message.includes('hola') ||
  message.includes('buenos') ||
  message.includes('buenas') ||
  message.includes('hey')
) {
  intent = 'greeting';
}

// Extract date/time hints
const datePatterns = [
  /\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}/,
  /lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado/i,
  /mañana|pasado mañana|hoy/i,
  /(\d{1,2})\s*(am|pm|de la mañana|de la tarde)/i,
];
let dateHint = null;
for (const pattern of datePatterns) {
  const match = message.match(pattern);
  if (match) { dateHint = match[0]; break; }
}

// Extract name hint (after 'me llamo' or 'soy')
const nameMatch = message.match(/(?:me llamo|soy|mi nombre es)\s+([A-ZÁÉÍÓÚÑa-záéíóúñ ]+)/i);
const nameHint = nameMatch ? nameMatch[1].trim() : null;

// Extract phone
const phoneMatch = message.match(/(\+?\d[\d\s\-\.]{8,15}\d)/);
const phoneHint = phoneMatch ? phoneMatch[1] : null;

return [{
  json: {
    originalMessage: body.message,
    sessionId,
    intent,
    dateHint,
    nameHint,
    phoneHint,
    lowerMessage: message,
  }
}];

// Check if we have enough info to create the appointment
const data = $input.first().json;
const hasDate = !!data.dateHint;
const hasName = !!data.nameHint;
const hasPhone = !!data.phoneHint;

if (!hasName && !hasDate) {
  return [{
    json: {
      ...data,
      readyToBook: false,
      output: '¡Con mucho gusto agendo tu cita! 📅\n\nNecesito algunos datos:\n\n• **Tu nombre completo**\n• **Fecha y hora preferida** (Lu–Sa, 10am–7pm)\n• **Tu número de teléfono**\n\nPor ejemplo: "Me llamo Juan Pérez, quiero el martes a las 11am, mi teléfono es 33 1234 5678"',
    }
  }];
}

if (!hasDate) {
  return [{
    json: {
      ...data,
      readyToBook: false,
      output: `Gracias ${data.nameHint || ''}. ¿Qué fecha y hora prefieres para tu cita? 📅\n\nAtendemos **lunes a sábado de 10:00 am a 7:00 pm**.`,
    }
  }];
}

if (!hasName) {
  return [{
    json: {
      ...data,
      readyToBook: false,
      output: `Perfecto, anotado para el ${data.dateHint}. ¿Me puedes dar tu nombre completo y número de teléfono para confirmar la cita?`,
    }
  }];
}

// We have enough info
return [{
  json: {
    ...data,
    readyToBook: true,
    output: null,
  }
}];

const data = $input.first().json;

// Parse the date hint into an actual datetime
// This is a simplified parser — in production connect to an AI node for NLP
const today = new Date();
const dayMap = {
  'lunes': 1, 'martes': 2, 'miércoles': 3, 'miercoles': 3,
  'jueves': 4, 'viernes': 5, 'sábado': 6, 'sabado': 6
};

let targetDate = new Date();

const hint = (data.dateHint || '').toLowerCase();

// Check for day names
for (const [dayName, dayNum] of Object.entries(dayMap)) {
  if (hint.includes(dayName)) {
    const diff = (dayNum - today.getDay() + 7) % 7 || 7;
    targetDate = new Date(today);
    targetDate.setDate(today.getDate() + diff);
    break;
  }
}

// Check for mañana
if (hint.includes('mañana')) {
  targetDate = new Date(today);
  targetDate.setDate(today.getDate() + 1);
}

// Default time: 10am if none specified
let hour = 10;
const hourMatch = hint.match(/(\d{1,2})\s*(pm|am)?/);
if (hourMatch) {
  hour = parseInt(hourMatch[1]);
  if (hourMatch[2] === 'pm' && hour < 12) hour += 12;
}

// Clamp to business hours 10–19
hour = Math.max(10, Math.min(19, hour));

targetDate.setHours(hour, 0, 0, 0);
const endDate = new Date(targetDate);
endDate.setHours(hour + 1, 0, 0, 0);

// Validate: no Sundays
if (targetDate.getDay() === 0) {
  return [{
    json: {
      ...data,
      readyToBook: false,
      output: 'Lo sentimos, los domingos no tenemos consulta. Atendemos **lunes a sábado de 10:00 am a 7:00 pm**. ¿Te acomoda otro día?',
    }
  }];
}

const dateISO = targetDate.toISOString();
const endISO = endDate.toISOString();
const friendlyDate = targetDate.toLocaleDateString('es-MX', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});
const friendlyTime = targetDate.toLocaleTimeString('es-MX', {
  hour: '2-digit', minute: '2-digit'
});

return [{
  json: {
    ...data,
    dateISO,
    endISO,
    friendlyDate,
    friendlyTime,
    calendarSummary: `Consulta – ${data.nameHint || 'Paciente'}`,
    calendarDescription: `Paciente: ${data.nameHint || 'N/D'}\nTeléfono: ${data.phoneHint || 'N/D'}\nAgendado vía chatbot web.`,
  }
}];

const data = $input.first().json;
const name = data.nameHint || 'Estimado paciente';
const date = data.friendlyDate || 'la fecha solicitada';
const time = data.friendlyTime || '';

return [{
  json: {
    output: `✅ ¡Cita agendada exitosamente, ${name}!\n\n📅 **${date}**\n🕐 **${time}**\n📍 Av. Américas 1254, Piso 3, Guadalajara\n\nRecibirás un recordatorio por correo 24 horas antes. Si necesitas reagendar o cancelar, llámanos al +52 (33) 1234-5678.\n\n¡El Dr. Yamamoto Ishikawa los espera! 🩺`,
  }
}];

const data = $input.first().json;
return [{
  json: {
    output: data.output || '¿Podría proporcionarme más detalles para continuar con tu cita?',
  }
}];

return [{
  json: {
    output: '🕐 **Horarios de atención:**

• Lunes – Viernes: 10:00 am – 7:00 pm
• Sábado: 10:00 am – 3:00 pm
• Domingo: Cerrado

📍 Av. Américas 1254, Piso 3, Guadalajara, Jalisco
📞 +52 (33) 1234-5678

¿Te gustaría agendar una cita?',
  }
}];

return [{
  json: {
    output: '🩺 **Especialidades del Dr. Yamamoto Ishikawa:**

• **Cirugía General** – Procedimientos de alta complejidad
• **Cirugía Laparoscópica** – Vesícula, apéndice, colon y más
• **Cirugía de Urgencias** – Atención inmediata 24/7
• **Cirugía Bariátrica** – Manga gástrica y bypass
• **Consulta Preoperatoria** – Evaluación y protocolo
• **Seguimiento Postoperatorio** – Acompañamiento en recuperación

¿Te gustaría agendar una consulta de evaluación?',
  }
}];

