  }
}];

// Merge all possible response paths into a single output
const data = $input.first().json;
return [{ json: { output: data.output || 'No pude procesar tu solicitud. Por favor llámanos al +52 (33) 1234-5678.' } }];

// Error handler for Google Calendar failures
const err = $input.first().json;
console.error('Calendar error:', JSON.stringify(err));
return [{
  json: {
    output: 'Tuvimos un problema al registrar tu cita en el calendario. Por favor llámanos directamente al **+52 (33) 1234-5678** para confirmar tu reserva. ¡Disculpa el inconveniente!',
  }
}];
